import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows strong association with outcome
    p_values = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # Skip clinical/cohort variables for driver selection
            continue
        # Use Welch's t-test for continuous features
        if feats.types[i] in ('expression', 'copy_number'):
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)
            p_values.append((p_val, fid))

    # Sort by p-value
    p_values.sort()

    # If no significant features, return empty design
    if not p_values or p_values[0][0] > 0.05:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features based on significance
    selected_features = [fid for _, fid in p_values[:MAX_DRIVERS]]

    # Check for near-duplicates (correlated features)
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Remove near-duplicates
    to_remove = set()
    for (fid1, fid2), _ in correlations.items():
        if fid1 in selected_features and fid2 in selected_features:
            # Keep the one with better p-value
            for k, (p_val, fid) in enumerate(p_values):
                if fid == fid1:
                    idx1 = k
                elif fid == fid2:
                    idx2 = k
            if p_values[idx1][0] > p_values[idx2][0]:
                to_remove.add(fid1)
            else:
                to_remove.add(fid2)

    final_drivers = tuple(f for f in selected_features if f not in to_remove)

    # Build loadings using top features
    loadings = {}
    for fid in final_drivers:
        idx = feats.column(fid)
        # Weight by effect size (inverse of p-value, capped)
        for p_val, f in p_values:
            if f == fid:
                weight = min(10, 1 / max(p_val, 1e-10))
                loadings[fid] = weight
                break

    # Include all features with significant associations
    columns = tuple(selected_features)
    products = ()

    return Design(drivers=final_drivers, columns=columns, products=products, loadings=loadings)

